describe('Expired Promo Code Error', () => {
  beforeEach(() => {
    cy.visit('/checkout');
    cy.get('[data-testid="promo-code-input"]').should('be.visible');
  });

  it('should display error message when entering an expired promo code', () => {
    cy.get('[data-testid="promo-code-input"]').type('EXPIRED2023');
    cy.get('[data-testid="apply-promo-button"]').click();

    cy.get('[data-testid="promo-error-message"]')
      .should('be.visible')
      .and('contain', 'This promo code has expired');

    cy.get('[data-testid="discount-amount"]').should('not.exist');
  });

  it('should clear error message when user corrects the promo code', () => {
    cy.get('[data-testid="promo-code-input"]').type('EXPIRED2023');
    cy.get('[data-testid="apply-promo-button"]').click();

    cy.get('[data-testid="promo-error-message"]').should('be.visible');

    cy.get('[data-testid="promo-code-input"]').clear().type('VALID2024');
    cy.get('[data-testid="apply-promo-button"]').click();

    cy.get('[data-testid="promo-error-message"]').should('not.exist');
    cy.get('[data-testid="discount-amount"]').should('be.visible');
  });

  it('should handle multiple expired promo code attempts', () => {
    const expiredCodes = ['EXPIRED2023', 'OLD2022', 'PAST2021'];

    expiredCodes.forEach((code) => {
      cy.get('[data-testid="promo-code-input"]').clear().type(code);
      cy.get('[data-testid="apply-promo-button"]').click();

      cy.get('[data-testid="promo-error-message"]')
        .should('be.visible')
        .and('contain', 'This promo code has expired');
    });
  });

  it('should display error immediately for empty promo code submission', () => {
    cy.get('[data-testid="promo-code-input"]').should('have.value', '');
    cy.get('[data-testid="apply-promo-button"]').click();

    cy.get('[data-testid="promo-error-message"]')
      .should('be.visible')
      .and('contain', 'Please enter a promo code');
  });
});
